挖到关键线索：**电鸭社区已变成外包私活发布平台**、**试卷数字化 10 元/张长期兼职**。最后补一轮。

[tool-call run_code] {"timeoutMs": 300000, "code": "
const [a, b] = await Promise.all([
 tools.web_search({ queries: [
 "电鸭社区 远程工作 外包 私活 发布 2026",
 "电鸭 兼职 招聘 2026 现状",
 "云费用优化咨询 5万 1.5天 V2EX 复盘",
 ]}),
 tools.web_search({ queries: [
 "试卷数字化 转换 兼职 10元一张 2026",
 "manim 代写 安装 副业 学生",
 "GitHub 赏金 bounty 赚钱 1w 复盘",
 ]}),
]);
const dump = (n: string, s: any) => {
 console.log("════ " + n + " ════");
 console.log(s.sources.slice(0, 12).map(x => `- [${x.title ?? "?"}](${x.url})\n ${(x.snippet ?? "").slice(0, 175)}`).join("\n"));
};
dump("A 电鸭/云优化", a); dump("B 试卷/manim/赏金", b);
